{v:'VER',what:'cloud-raid-p2clear: player 2 SCREEN CLEAR sends the host blows it takes, so the machines on his screen die on the host as nobody kill, it charges no air strike meter, and he is paid the SCREEN CLEAR medal',
 run:function(){
   if(!(window.__state&&window.__runPrep)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof pwrPulse!=='function'||typeof netShotTake!=='function'||typeof airS!=='function'||typeof mkCrawler!=='function') return 'SKIP: no arcade, power-ups or party in this fixture';
   var g=null, p=null, rs=say, own=false, oSty,  NK={}, k, oS=netSend, oSF=netSendFast, posted=[], h={seat:0,state:'in'}, hp={seat:1,state:'in'}, es=[], j, e, A, a0, oE=null, oPw, staged=false, bad=[], took;
   try{
     __topClear(); __runPrep();
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     p=g.player; keys={}; say=function(){}; own=true; oPw=g.pwr; oSty=g.sty; oE=g.ents.slice();
     g.ents=g.ents.filter(function(q){ return q&&(q.neutral||q.kind==='peddler'||q.kind==='stray'); });
     for(k in NET) NK[k]=NET[k]; staged=true;
     NET.on=true; NET.max=4; NET.specG=null; NET.up=[]; NET.upSeed=g.seed>>>0;
     netSendFast=function(q,m){ return true; }; netSend=function(q,m){ posted.push(JSON.parse(JSON.stringify(m))); return true; };
     NET.role='join'; NET.seat=1; NET.peers=[h];
     if(!netEntsPeer()) return 'SKIP: staging: the linked window does not take the host bodies';
     NET.entMap={};
     for(j=0;j<3;j++){ e=mkCrawler(p.x+90+j*40,p.y+20); e.elite=0; e.boss=0; e.nid=900+j; es.push(e); g.ents.push(e); NET.entMap[e.nid]=e; }
     render2D(0);
     A=airS(); a0=A.m;
     g.pwr=null; pwrS();
     posted.length=0; pwrPulse(p);
     if(!posted.some(function(m){ return m.t==='shot'; })) return 'SKIP: staging: the clear sent no blow to the host';
     if(!styS().pops.some(function(q){ return q&&q.txt==='SCREEN CLEAR'; })) bad.push('player 2 was not paid the SCREEN CLEAR medal');
     if(A.m!==a0) bad.push('the clear charged the air strike meter from '+a0+' to '+A.m);
     NET.role='host'; NET.seat=0; NET.peers=[hp];
     took=posted.filter(function(m){ return m.t==='shot'; }).map(function(m){ return netShotTake(hp,m); });
     for(j=0;j<es.length;j++){ if(es[j].hp>0) bad.push('machine '+j+' still has '+es[j].hp+' on the host (host answered '+took[j]+')'); else if(es[j].bySeat!==0||es[j].byPlayer!==false) bad.push('machine '+j+' was credited to seat '+es[j].bySeat+' (a clear kill is nobody kill)'); }
     return bad.length?bad.join('; '):null;
   }catch(x){ return 'threw: '+(x&&x.stack||x); }
   finally{
     if(own) say=rs; netSend=oS; netSendFast=oSF;
     if(staged){ for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; }
     if(g){ if(oE) g.ents=oE; g.pwr=oPw; g.sty=oSty; }
     try{ __endRaid('abandon'); }catch(_e){} try{ __topClear(); }catch(_t){}
   }
 }},
